function confetti(){
  if (reduced) return;
  const r = card.getBoundingClientRect();
  const cx = r.left + r.width/2, cy = r.top + r.height/2;
  const colors = ['#f5c542','#e8452c','#f6efe0','#3fb9a0'];
  for (let k=0;k<26;k++){
    const c = document.createElement('div');
    c.className = 'confetti';
    const a = Math.random()*Math.PI*2, d = 90 + Math.random()*140;
    c.style.left = cx + Math.cos(a)*d + 'px';
    c.style.top = cy + Math.sin(a)*d + 'px';
    c.style.background = colors[k%colors.length];
    c.style.setProperty('--dx', (Math.cos(a)*d*0.9).toFixed(0)+'px');
    c.style.setProperty('--dy', (Math.sin(a)*d*0.9 + 60).toFixed(0)+'px');
    c.style.setProperty('--rot', (Math.random()*720-360).toFixed(0)+'deg');
    document.body.appendChild(c);
    setTimeout(()=>c.remove(), 1200);
  }
}
